def _get_glyphs(component, glyph_set):
    """Return the glyphs of `component`."""
    return [glyph_set.get_glyph(g) for g in component.get_glyphs()]


def _get_glyph_names(component, glyph_set):
    """Return the glyph names of `component`."""
    return [glyph_set.get_glyph(g).name for g in component.get_glyphs()]


